#!/usr/bin/env python3
"""
Ledger — Trade Journal v2
Single-file, dependency-free web app designed for Render.

Important for Render:
- Set DATA_DIR to a persistent disk mount path if you want trades to survive deploys/restarts.
  Example: DATA_DIR=/var/data
"""

import base64
import json
import math
import os
import tempfile
import threading
import uuid
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit

PORT = int(os.environ.get("PORT", "8000"))
DATA_DIR = os.environ.get("DATA_DIR", ".")
JOURNAL_FILE = os.path.join(DATA_DIR, "journal.json")
MAX_BODY_BYTES = 6 * 1024 * 1024
ALLOWED_TYPES = {"stock", "forex", "crypto", "indice", "future"}
ALLOWED_SIDES = {"long", "short"}
LOCK = threading.RLock()
JOURNAL = []

ICON_512_B64 = ''
ICON_192_B64 = ''
ICON_180_B64 = ''
SPLASH_BG_B64 = ''

PAGE_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">\n<meta name="theme-color" content="#080b14">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n<meta name="apple-mobile-web-app-title" content="Ledger">\n<link rel="manifest" href="/manifest.json">\n<link rel="apple-touch-icon" href="/apple-touch-icon.png">\n<link rel="icon" href="/icon-192.png">\n<title>Ledger — Trade Journal</title>\n<style>\n@import url(\'https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=Sora:wght@600;700;800&display=swap\');\n\n:root {\n  --bg:#080b14; --panel:#0f1422; --panel2:#131a2b; --line:rgba(255,255,255,.08);\n  --text:#f4f5f7; --muted:#8e99ad; --muted2:#657086; --accent:#e8b450;\n  --green:#3ddc97; --red:#ff6b67; --blue:#75a7ff; --radius:18px;\n}\n*{box-sizing:border-box}\nhtml{background:var(--bg);color-scheme:dark}\nbody{\n  margin:0; min-height:100vh; color:var(--text); font-family:Manrope,system-ui,sans-serif;\n  background:\n    radial-gradient(900px 500px at 12% -5%,rgba(92,110,255,.14),transparent 60%),\n    radial-gradient(700px 420px at 95% 0%,rgba(232,180,80,.10),transparent 55%),\n    var(--bg);\n}\nbutton,input,select,textarea{font:inherit}\nbutton{cursor:pointer}\nbutton:disabled{opacity:.55;cursor:not-allowed}\n\n.splash{position:fixed;inset:0;z-index:9999;display:grid;place-items:center;background:#080b14;transition:.35s ease}\n.splash.hide{opacity:0;pointer-events:none}\n.splash-logo{font-family:Sora;font-size:42px;font-weight:800;letter-spacing:-2px}.splash-logo span{color:var(--accent)}\n\n.shell{width:min(1180px,calc(100% - 32px));margin:0 auto;padding:26px 0 60px}\nheader{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:26px}\n.brand h1{font:800 32px/1 Sora;margin:0;letter-spacing:-1.6px}.brand h1 span{color:var(--accent)}\n.brand p{margin:8px 0 0;color:var(--muted);font-size:13px}\n.top-pnl{text-align:right}.top-pnl strong{display:block;font:800 28px/1 Sora}.top-pnl span{display:block;color:var(--muted);font-size:12px;margin-top:7px}\n\n.grid{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}\n.card{\n  background:linear-gradient(180deg,rgba(255,255,255,.055),rgba(255,255,255,.03));\n  border:1px solid var(--line); border-radius:var(--radius); box-shadow:0 18px 50px rgba(0,0,0,.22);\n}\n.stat{padding:17px}.label{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.08em;font-weight:800}\n.value{font:700 22px/1.1 Sora;margin-top:10px}.sub{font-size:11px;color:var(--muted2);margin-top:7px}\n.pos{color:var(--green)!important}.neg{color:var(--red)!important}\n\n.chart-wrap{display:grid;grid-template-columns:minmax(0,2fr) minmax(260px,.8fr);gap:12px;margin-top:12px}\n.chart-card{padding:20px;min-height:292px}.chart-head{display:flex;justify-content:space-between;align-items:start;gap:16px;margin-bottom:12px}\n.chart-head h2{font:700 18px Sora;margin:0}.chart-head p{margin:5px 0 0;color:var(--muted);font-size:12px}\n.chart-chip{font-size:12px;border:1px solid var(--line);border-radius:999px;padding:7px 10px;color:var(--muted);white-space:nowrap}\ncanvas{display:block;width:100%;height:210px}\n\n.insights{padding:20px}.insights h2{font:700 18px Sora;margin:0 0 14px}\n.insight-row{display:flex;justify-content:space-between;gap:16px;padding:12px 0;border-top:1px solid var(--line)}\n.insight-row:first-of-type{border-top:0}.insight-row span{color:var(--muted);font-size:12px}.insight-row strong{font-size:13px;text-align:right}\n\n.toolbar{display:flex;align-items:center;gap:10px;margin:18px 0 12px;flex-wrap:wrap}\n.primary,.secondary,.danger-btn{\n  border-radius:12px;border:1px solid var(--line);padding:10px 14px;font-weight:800;font-size:13px;\n}\n.primary{background:var(--accent);color:#211600;border-color:transparent}.primary:hover{filter:brightness(1.05)}\n.secondary{background:rgba(255,255,255,.04);color:var(--text)}.secondary:hover{background:rgba(255,255,255,.07)}\n.danger-btn{background:rgba(255,107,103,.10);color:var(--red);border-color:rgba(255,107,103,.22)}\n\n.filters{display:grid;grid-template-columns:1.2fr repeat(4,.7fr);gap:10px;padding:12px;margin-bottom:12px}\n.field-control{\n  width:100%;background:#0c111e;color:var(--text);border:1px solid var(--line);border-radius:11px;padding:10px 11px;outline:none;\n}\n.field-control:focus{border-color:rgba(232,180,80,.65);box-shadow:0 0 0 3px rgba(232,180,80,.08)}\n\n.list{display:grid;gap:10px}\n.trade{padding:17px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:16px}\n.trade-main{min-width:0}.trade-top{display:flex;align-items:center;gap:9px;flex-wrap:wrap}\n.symbol{font:800 19px Sora}.pill{font-size:10px;text-transform:uppercase;letter-spacing:.05em;font-weight:800;padding:4px 7px;border-radius:999px;background:rgba(117,167,255,.10);color:var(--blue)}\n.side-long{color:var(--green);background:rgba(61,220,151,.09)}.side-short{color:var(--red);background:rgba(255,107,103,.09)}\n.trade-date{color:var(--muted);font-size:11px}\n.trade-pnl{font:800 19px Sora;margin-left:auto}\n.meta{display:flex;gap:8px 14px;flex-wrap:wrap;margin-top:10px;color:var(--muted);font-size:12px}\n.notes{margin:11px 0 0;color:#cbd1dc;font-size:12px;line-height:1.55;white-space:pre-wrap}\n.tags{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.tag{font-size:10px;padding:4px 7px;border-radius:999px;background:rgba(255,255,255,.05);color:#aeb7c8}\n.thumb{width:106px;height:72px;object-fit:cover;border-radius:10px;border:1px solid var(--line);margin-top:12px}\n.trade-actions{display:flex;gap:7px;align-items:start}.icon-btn{border:1px solid var(--line);background:rgba(255,255,255,.035);color:var(--muted);border-radius:9px;padding:7px 9px;font-size:11px}\n.icon-btn:hover{color:var(--text);background:rgba(255,255,255,.07)}\n.empty{padding:42px 20px;text-align:center;color:var(--muted)}.empty strong{display:block;color:var(--text);font:700 18px Sora;margin-bottom:7px}\n\n.modal{position:fixed;inset:0;background:rgba(0,0,0,.66);backdrop-filter:blur(10px);display:none;place-items:center;padding:18px;z-index:100}\n.modal.open{display:grid}.sheet{width:min(760px,100%);max-height:min(90vh,860px);overflow:auto;background:#0c111d;border:1px solid var(--line);border-radius:22px;padding:22px;box-shadow:0 30px 100px rgba(0,0,0,.55)}\n.modal-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.modal-head h2{font:700 22px Sora;margin:0}.x{background:none;border:0;color:var(--muted);font-size:22px}\n.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:13px;margin-top:20px}.full{grid-column:1/-1}\nlabel{display:block;color:var(--muted);font-size:11px;font-weight:800;margin-bottom:7px;text-transform:uppercase;letter-spacing:.06em}\ntextarea.field-control{min-height:90px;resize:vertical}\n.tag-picker{display:flex;gap:7px;flex-wrap:wrap}.tag-btn{border:1px solid var(--line);background:rgba(255,255,255,.03);color:var(--muted);border-radius:999px;padding:7px 10px;font-size:11px}\n.tag-btn.selected{background:rgba(232,180,80,.14);border-color:rgba(232,180,80,.35);color:#f3ca79}\n.preview img{max-width:100%;max-height:220px;border-radius:12px;margin-top:10px;border:1px solid var(--line)}\n.form-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:18px}.status{font-size:12px;color:var(--muted)}\n.lightbox .sheet{width:min(1100px,96vw);padding:8px;background:#05070c}.lightbox img{display:block;max-width:100%;max-height:90vh;margin:auto;border-radius:12px}\n\n.toast{position:fixed;right:18px;bottom:18px;z-index:200;background:#151d2d;border:1px solid var(--line);border-radius:12px;padding:11px 14px;font-size:12px;box-shadow:0 18px 60px rgba(0,0,0,.4);transform:translateY(20px);opacity:0;pointer-events:none;transition:.2s}\n.toast.show{transform:none;opacity:1}\n\n@media(max-width:980px){.grid{grid-template-columns:repeat(3,1fr)}.chart-wrap{grid-template-columns:1fr}.filters{grid-template-columns:repeat(2,1fr)}}\n@media(max-width:620px){\n  .shell{width:min(100% - 20px,1180px);padding-top:18px} header{align-items:start}.brand h1{font-size:27px}.top-pnl strong{font-size:22px}\n  .grid{grid-template-columns:repeat(2,1fr)}.stat{padding:14px}.value{font-size:18px}.filters{grid-template-columns:1fr}\n  .trade{grid-template-columns:1fr}.trade-actions{order:2}.trade-pnl{margin-left:0}.form-grid{grid-template-columns:1fr}.full{grid-column:auto}.sheet{padding:18px}\n}\n</style>\n</head>\n<body>\n<div class="splash" id="splash"><div class="splash-logo">Ledger<span>.</span></div></div>\n\n<main class="shell">\n<header>\n  <div class="brand"><h1>Ledger<span>.</span></h1><p>Trade journal • review execution, not just outcomes</p></div>\n  <div class="top-pnl"><strong id="headerPnl">$0.00</strong><span id="headerPnlLabel">0 trades logged</span></div>\n</header>\n\n<section class="grid">\n  <div class="card stat"><div class="label">Total P&L</div><div class="value" id="sTotal">$0.00</div><div class="sub" id="sTotalSub">0 trades</div></div>\n  <div class="card stat"><div class="label">Win rate</div><div class="value" id="sWin">—</div><div class="sub" id="sWinSub">0 wins / 0 losses</div></div>\n  <div class="card stat"><div class="label">Avg trade</div><div class="value" id="sAvg">$0.00</div><div class="sub">average realized P&L</div></div>\n  <div class="card stat"><div class="label">Profit factor</div><div class="value" id="sPF">—</div><div class="sub">gross wins ÷ gross losses</div></div>\n  <div class="card stat"><div class="label">Best trade</div><div class="value pos" id="sBest">—</div><div class="sub" id="sBestSub">no trades yet</div></div>\n  <div class="card stat"><div class="label">Worst trade</div><div class="value neg" id="sWorst">—</div><div class="sub" id="sWorstSub">no trades yet</div></div>\n</section>\n\n<section class="chart-wrap">\n  <div class="card chart-card">\n    <div class="chart-head"><div><h2>Equity curve</h2><p>Cumulative realized P&L in journal order</p></div><div class="chart-chip" id="drawdownChip">Max DD $0.00</div></div>\n    <canvas id="chart"></canvas>\n  </div>\n  <aside class="card insights">\n    <h2>Quick review</h2>\n    <div class="insight-row"><span>Most traded setup</span><strong id="iSetup">—</strong></div>\n    <div class="insight-row"><span>Best instrument type</span><strong id="iType">—</strong></div>\n    <div class="insight-row"><span>Average winner</span><strong id="iWin">—</strong></div>\n    <div class="insight-row"><span>Average loser</span><strong id="iLoss">—</strong></div>\n    <div class="insight-row"><span>Expectancy / trade</span><strong id="iExpectancy">—</strong></div>\n  </aside>\n</section>\n\n<div class="toolbar">\n  <button class="primary" onclick="openTradeForm()">+ Log trade</button>\n  <button class="secondary" onclick="exportCsv()">Export CSV</button>\n  <button class="secondary" onclick="exportJson()">Backup JSON</button>\n  <span style="flex:1"></span>\n  <button class="secondary" onclick="clearFilters()">Clear filters</button>\n</div>\n\n<section class="card filters">\n  <input class="field-control" id="fSearch" placeholder="Search symbol, setup, notes…" oninput="renderList()">\n  <select class="field-control" id="fType" onchange="renderList()"><option value="">All instruments</option><option value="stock">Stock</option><option value="forex">Forex</option><option value="crypto">Crypto</option><option value="indice">Index</option><option value="future">Future</option></select>\n  <select class="field-control" id="fResult" onchange="renderList()"><option value="">All results</option><option value="win">Wins only</option><option value="loss">Losses only</option><option value="be">Breakeven</option></select>\n  <input class="field-control" type="date" id="fFrom" onchange="renderList()">\n  <input class="field-control" type="date" id="fTo" onchange="renderList()">\n</section>\n\n<section class="list" id="tradeList"></section>\n</main>\n\n<div class="modal" id="tradeModal" onclick="if(event.target===this) closeTradeForm()">\n  <div class="sheet">\n    <div class="modal-head"><h2 id="formTitle">Log a trade</h2><button class="x" onclick="closeTradeForm()" aria-label="Close">×</button></div>\n    <div class="form-grid">\n      <div><label>Date</label><input class="field-control" type="date" id="tf-date"></div>\n      <div><label>Instrument</label><select class="field-control" id="tf-type"><option value="stock">Stock</option><option value="forex">Forex</option><option value="crypto">Crypto</option><option value="indice">Index</option><option value="future">Future</option></select></div>\n      <div><label>Symbol</label><input class="field-control" id="tf-symbol" placeholder="AAPL / EURUSD"></div>\n      <div><label>Side</label><select class="field-control" id="tf-side"><option value="long">Long</option><option value="short">Short</option></select></div>\n      <div><label>Realized P&L ($)</label><input class="field-control" type="number" step="0.01" id="tf-pnl" placeholder="125.50"></div>\n      <div><label>Risk : Reward</label><input class="field-control" id="tf-rr" placeholder="1:2.3"></div>\n      <div><label>Entry</label><input class="field-control" id="tf-entry" placeholder="2.16"></div>\n      <div><label>Exit</label><input class="field-control" id="tf-exit" placeholder="2.31"></div>\n      <div class="full"><label>Setup / pattern</label><input class="field-control" id="tf-pattern" placeholder="Bull flag, ORB, breakout retest…"></div>\n      <div class="full"><label>Notes / review</label><textarea class="field-control" id="tf-notes" placeholder="Why did you enter? What went well? What would you change?"></textarea></div>\n      <div class="full">\n        <label>Tags</label>\n        <div class="tag-picker" id="tagPicker">\n          <button type="button" class="tag-btn" data-tag="Planned">Planned</button>\n          <button type="button" class="tag-btn" data-tag="Disciplined">Disciplined</button>\n          <button type="button" class="tag-btn" data-tag="Patient">Patient</button>\n          <button type="button" class="tag-btn" data-tag="FOMO">FOMO</button>\n          <button type="button" class="tag-btn" data-tag="Revenge trade">Revenge trade</button>\n          <button type="button" class="tag-btn" data-tag="Overtraded">Overtraded</button>\n          <button type="button" class="tag-btn" data-tag="Hesitant">Hesitant</button>\n        </div>\n      </div>\n      <div class="full"><label>Trade screenshot</label><input class="field-control" type="file" id="tf-screenshot" accept="image/png,image/jpeg,image/webp"><div class="preview" id="preview"></div></div>\n    </div>\n    <div class="form-footer"><div class="status" id="formStatus"></div><button class="primary" id="saveBtn" onclick="submitTrade()">Save trade</button></div>\n  </div>\n</div>\n\n<div class="modal lightbox" id="lightbox" onclick="closeLightbox()"><div class="sheet"><img id="lightboxImg" alt="Trade screenshot"></div></div>\n<div class="toast" id="toast"></div>\n\n<script>\nlet TRADES = [];\nlet EDIT_ID = null;\nlet PENDING_SCREENSHOT = "";\n\nconst $ = (id) => document.getElementById(id);\nconst money = (n) => `${Number(n)<0?\'-\':\'\'}$${Math.abs(Number(n)||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}`;\nconst esc = (v) => String(v ?? \'\').replace(/[&<>"\']/g, c => ({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst pnlClass = (n) => Number(n)>0?\'pos\':Number(n)<0?\'neg\':\'\';\nfunction showToast(msg){ const t=$(\'toast\'); t.textContent=msg; t.classList.add(\'show\'); clearTimeout(showToast.timer); showToast.timer=setTimeout(()=>t.classList.remove(\'show\'),2200); }\n\nfunction stats() {\n  const pnls = TRADES.map(t=>Number(t.pnl)||0);\n  const wins = pnls.filter(x=>x>0), losses=pnls.filter(x=>x<0);\n  const total=pnls.reduce((a,b)=>a+b,0), count=pnls.length;\n  const grossWin=wins.reduce((a,b)=>a+b,0), grossLoss=Math.abs(losses.reduce((a,b)=>a+b,0));\n  const best=count?Math.max(...pnls):null, worst=count?Math.min(...pnls):null;\n  const avg=count?total/count:0, winRate=count?(wins.length/count)*100:null;\n  const pf=grossLoss>0?grossWin/grossLoss:(grossWin>0?Infinity:null);\n  const avgWin=wins.length?grossWin/wins.length:null, avgLoss=losses.length?losses.reduce((a,b)=>a+b,0)/losses.length:null;\n  return {total,count,wins,losses,best,worst,avg,winRate,pf,avgWin,avgLoss};\n}\nfunction renderHeaderStats(){\n  const s=stats();\n  $(\'headerPnl\').textContent=money(s.total); $(\'headerPnl\').className=pnlClass(s.total);\n  $(\'headerPnlLabel\').textContent=`${s.count} trade${s.count===1?\'\':\'s\'} logged`;\n  $(\'sTotal\').textContent=money(s.total); $(\'sTotal\').className=`value ${pnlClass(s.total)}`;\n  $(\'sTotalSub\').textContent=`${s.count} trade${s.count===1?\'\':\'s\'}`;\n  $(\'sWin\').textContent=s.winRate===null?\'—\':`${s.winRate.toFixed(0)}%`;\n  $(\'sWinSub\').textContent=`${s.wins.length} wins / ${s.losses.length} losses`;\n  $(\'sAvg\').textContent=money(s.avg); $(\'sAvg\').className=`value ${pnlClass(s.avg)}`;\n  $(\'sPF\').textContent=s.pf===null?\'—\':s.pf===Infinity?\'∞\':s.pf.toFixed(2);\n  const bestTrade=s.best===null?null:TRADES.find(t=>(Number(t.pnl)||0)===s.best);\n  const worstTrade=s.worst===null?null:TRADES.find(t=>(Number(t.pnl)||0)===s.worst);\n  $(\'sBest\').textContent=s.best===null?\'—\':money(s.best); $(\'sBestSub\').textContent=bestTrade?bestTrade.symbol:\'no trades yet\';\n  $(\'sWorst\').textContent=s.worst===null?\'—\':money(s.worst); $(\'sWorstSub\').textContent=worstTrade?worstTrade.symbol:\'no trades yet\';\n  $(\'iWin\').textContent=s.avgWin===null?\'—\':money(s.avgWin);\n  $(\'iLoss\').textContent=s.avgLoss===null?\'—\':money(s.avgLoss);\n  $(\'iExpectancy\').textContent=s.count?money(s.total/s.count):\'—\';\n\n  const setups={}; const types={};\n  for(const t of TRADES){ if(t.pattern) setups[t.pattern]=(setups[t.pattern]||0)+1; const ty=t.type||\'other\'; (types[ty]??=[]).push(Number(t.pnl)||0); }\n  const topSetup=Object.entries(setups).sort((a,b)=>b[1]-a[1])[0];\n  $(\'iSetup\').textContent=topSetup?`${topSetup[0]} (${topSetup[1]})`:\'—\';\n  const bestType=Object.entries(types).map(([k,v])=>[k,v.reduce((a,b)=>a+b,0)]).sort((a,b)=>b[1]-a[1])[0];\n  $(\'iType\').textContent=bestType?`${bestType[0]} · ${money(bestType[1])}`:\'—\';\n}\n\nfunction filteredTrades(){\n  const q=$(\'fSearch\').value.trim().toLowerCase(), type=$(\'fType\').value, result=$(\'fResult\').value, from=$(\'fFrom\').value, to=$(\'fTo\').value;\n  return TRADES.filter(t=>{\n    const pnl=Number(t.pnl)||0;\n    const hay=[t.symbol,t.pattern,t.notes,...(t.tags||[])].join(\' \').toLowerCase();\n    return (!q||hay.includes(q)) && (!type||t.type===type) &&\n      (!result||(result===\'win\'&&pnl>0)||(result===\'loss\'&&pnl<0)||(result===\'be\'&&pnl===0)) &&\n      (!from||t.date>=from)&&(!to||t.date<=to);\n  });\n}\nfunction renderList(){\n  const rows=filteredTrades(), root=$(\'tradeList\');\n  if(!rows.length){ root.innerHTML=`<div class="card empty"><strong>No matching trades</strong>Log a trade or change your filters.</div>`; return; }\n  root.innerHTML=rows.map(t=>{\n    const p=Number(t.pnl)||0;\n    return `<article class="card trade">\n      <div class="trade-main">\n        <div class="trade-top">\n          <span class="symbol">${esc(t.symbol)}</span>\n          <span class="pill">${esc(t.type||\'\')}</span>\n          <span class="pill side-${esc(t.side||\'long\')}">${esc(t.side||\'long\')}</span>\n          <span class="trade-date">${esc(t.date||\'\')}</span>\n          <span class="trade-pnl ${pnlClass(p)}">${money(p)}</span>\n        </div>\n        <div class="meta">\n          ${t.pattern?`<span><b>Setup:</b> ${esc(t.pattern)}</span>`:\'\'}\n          ${t.entry?`<span><b>Entry:</b> ${esc(t.entry)}</span>`:\'\'}\n          ${t.exit?`<span><b>Exit:</b> ${esc(t.exit)}</span>`:\'\'}\n          ${t.rr?`<span><b>R:R:</b> ${esc(t.rr)}</span>`:\'\'}\n        </div>\n        ${t.notes?`<div class="notes">${esc(t.notes)}</div>`:\'\'}\n        ${(t.tags||[]).length?`<div class="tags">${t.tags.map(x=>`<span class="tag">${esc(x)}</span>`).join(\'\')}</div>`:\'\'}\n        ${t.screenshot?`<img class="thumb" src="${t.screenshot}" alt="Trade screenshot" onclick="openLightbox(\'${t.id}\')">`:\'\'}\n      </div>\n      <div class="trade-actions">\n        <button class="icon-btn" onclick="editTrade(\'${t.id}\')">Edit</button>\n        <button class="icon-btn" onclick="deleteTrade(\'${t.id}\')">Delete</button>\n      </div>\n    </article>`;\n  }).join(\'\');\n}\n\nfunction drawChart(){\n  const c=$(\'chart\'), rect=c.getBoundingClientRect(), dpr=window.devicePixelRatio||1;\n  c.width=Math.max(1,Math.floor(rect.width*dpr)); c.height=Math.floor(210*dpr);\n  const ctx=c.getContext(\'2d\'), w=c.width,h=c.height; ctx.clearRect(0,0,w,h);\n  if(!TRADES.length){ctx.fillStyle=\'#657086\';ctx.font=`${13*dpr}px Manrope`;ctx.textAlign=\'center\';ctx.fillText(\'Log a trade to see your equity curve\',w/2,h/2);$(\'drawdownChip\').textContent=\'Max DD $0.00\';return;}\n  const ordered=[...TRADES].reverse(), points=[0]; let run=0, peak=0, maxDD=0;\n  for(const t of ordered){run+=Number(t.pnl)||0;points.push(run);peak=Math.max(peak,run);maxDD=Math.max(maxDD,peak-run);}\n  $(\'drawdownChip\').textContent=`Max DD ${money(-maxDD)}`;\n  const min=Math.min(0,...points),max=Math.max(0,...points),range=max-min||1,pad=14*dpr;\n  const x=i=>pad+(i/(points.length-1||1))*(w-pad*2), y=v=>pad+(1-(v-min)/range)*(h-pad*2);\n  const positive=points.at(-1)>=0, line=positive?\'#3ddc97\':\'#ff6b67\';\n  const zeroY=y(0);ctx.strokeStyle=\'rgba(255,255,255,.09)\';ctx.lineWidth=dpr;ctx.beginPath();ctx.moveTo(pad,zeroY);ctx.lineTo(w-pad,zeroY);ctx.stroke();\n  const grad=ctx.createLinearGradient(0,pad,0,h-pad);grad.addColorStop(0,positive?\'rgba(61,220,151,.20)\':\'rgba(255,107,103,.20)\');grad.addColorStop(1,\'rgba(0,0,0,0)\');\n  ctx.beginPath();points.forEach((v,i)=>i?ctx.lineTo(x(i),y(v)):ctx.moveTo(x(i),y(v)));ctx.lineTo(x(points.length-1),h-pad);ctx.lineTo(x(0),h-pad);ctx.closePath();ctx.fillStyle=grad;ctx.fill();\n  ctx.beginPath();points.forEach((v,i)=>i?ctx.lineTo(x(i),y(v)):ctx.moveTo(x(i),y(v)));ctx.strokeStyle=line;ctx.lineWidth=2*dpr;ctx.lineJoin=\'round\';ctx.lineCap=\'round\';ctx.stroke();\n}\nfunction renderAll(){renderHeaderStats();renderList();drawChart();}\nfunction clearFilters(){[\'fSearch\',\'fType\',\'fResult\',\'fFrom\',\'fTo\'].forEach(id=>$(id).value=\'\');renderList();}\n\ndocument.querySelectorAll(\'.tag-btn\').forEach(b=>b.addEventListener(\'click\',()=>b.classList.toggle(\'selected\')));\nfunction selectedTags(){return [...document.querySelectorAll(\'.tag-btn.selected\')].map(x=>x.dataset.tag)}\n\nfunction fillForm(t=null){\n  EDIT_ID=t?.id||null; $(\'formTitle\').textContent=t?\'Edit trade\':\'Log a trade\';\n  $(\'tf-date\').value=t?.date||new Date().toISOString().slice(0,10);\n  $(\'tf-type\').value=t?.type||\'stock\'; $(\'tf-symbol\').value=t?.symbol||\'\'; $(\'tf-side\').value=t?.side||\'long\';\n  $(\'tf-pnl\').value=t?.pnl ?? \'\'; $(\'tf-rr\').value=t?.rr||\'\'; $(\'tf-entry\').value=t?.entry||\'\'; $(\'tf-exit\').value=t?.exit||\'\';\n  $(\'tf-pattern\').value=t?.pattern||\'\'; $(\'tf-notes\').value=t?.notes||\'\'; $(\'formStatus\').textContent=\'\';\n  $(\'tf-screenshot\').value=\'\'; PENDING_SCREENSHOT=t?.screenshot||\'\'; $(\'preview\').innerHTML=PENDING_SCREENSHOT?`<img src="${PENDING_SCREENSHOT}">`:\'\';\n  document.querySelectorAll(\'.tag-btn\').forEach(b=>b.classList.toggle(\'selected\',(t?.tags||[]).includes(b.dataset.tag)));\n}\nfunction openTradeForm(){fillForm();$(\'tradeModal\').classList.add(\'open\');document.body.style.overflow=\'hidden\';setTimeout(()=>$(\'tf-symbol\').focus(),40)}\nfunction editTrade(id){const t=TRADES.find(x=>x.id===id);if(!t)return;fillForm(t);$(\'tradeModal\').classList.add(\'open\');document.body.style.overflow=\'hidden\'}\nfunction closeTradeForm(){$(\'tradeModal\').classList.remove(\'open\');document.body.style.overflow=\'\'}\n\n$(\'tf-screenshot\').addEventListener(\'change\',e=>{\n  const file=e.target.files?.[0]; if(!file)return;\n  if(file.size>10*1024*1024){$(\'formStatus\').textContent=\'Image is too large. Use one under 10 MB.\';e.target.value=\'\';return;}\n  const r=new FileReader();\n  r.onload=ev=>{const img=new Image();img.onload=()=>{\n    const maxW=1200, scale=Math.min(1,maxW/img.width), cv=document.createElement(\'canvas\');\n    cv.width=Math.max(1,Math.round(img.width*scale));cv.height=Math.max(1,Math.round(img.height*scale));\n    cv.getContext(\'2d\').drawImage(img,0,0,cv.width,cv.height);\n    PENDING_SCREENSHOT=cv.toDataURL(\'image/jpeg\',.78);$(\'preview\').innerHTML=`<img src="${PENDING_SCREENSHOT}">`;\n  };img.src=ev.target.result};r.readAsDataURL(file);\n});\n\nasync function api(path, options={}){\n  const res=await fetch(path,options); let data={};\n  try{data=await res.json()}catch{}\n  if(!res.ok) throw new Error(data.error||`Request failed (${res.status})`);\n  return data;\n}\nasync function submitTrade(){\n  const status=$(\'formStatus\'), save=$(\'saveBtn\'), symbol=$(\'tf-symbol\').value.trim().toUpperCase();\n  if(!symbol){status.textContent=\'Symbol is required.\';return}\n  const payload={date:$(\'tf-date\').value,type:$(\'tf-type\').value,symbol,side:$(\'tf-side\').value,pnl:$(\'tf-pnl\').value||0,rr:$(\'tf-rr\').value.trim(),entry:$(\'tf-entry\').value.trim(),exit:$(\'tf-exit\').value.trim(),pattern:$(\'tf-pattern\').value.trim(),notes:$(\'tf-notes\').value.trim(),tags:selectedTags(),screenshot:PENDING_SCREENSHOT};\n  status.textContent=\'Saving…\';save.disabled=true;\n  try{\n    const path=EDIT_ID?\'/api/journal-update\':\'/api/journal\'; if(EDIT_ID)payload.id=EDIT_ID;\n    const data=await api(path,{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(payload)});\n    TRADES=data.trades||TRADES;renderAll();closeTradeForm();showToast(EDIT_ID?\'Trade updated\':\'Trade saved\');\n  }catch(e){status.textContent=e.message||\'Could not save trade.\'}\n  finally{save.disabled=false}\n}\nasync function deleteTrade(id){\n  const t=TRADES.find(x=>x.id===id); if(!t)return;\n  if(!confirm(`Delete ${t.symbol} trade? This cannot be undone.`))return;\n  try{const data=await api(\'/api/journal-delete\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({id})});TRADES=data.trades||[];renderAll();showToast(\'Trade deleted\')}\n  catch(e){showToast(e.message||\'Delete failed\')}\n}\nfunction openLightbox(id){const t=TRADES.find(x=>x.id===id);if(!t?.screenshot)return;$(\'lightboxImg\').src=t.screenshot;$(\'lightbox\').classList.add(\'open\')}\nfunction closeLightbox(){$(\'lightbox\').classList.remove(\'open\')}\n\nfunction exportCsv(){\n  const trades=filteredTrades();if(!trades.length){showToast(\'No trades to export\');return}\n  const headers=[\'Date\',\'Type\',\'Side\',\'Symbol\',\'P&L\',\'Pattern\',\'Entry\',\'Exit\',\'Risk:Reward\',\'Tags\',\'Notes\'];\n  const rows=trades.map(t=>[t.date,t.type,t.side,t.symbol,Number(t.pnl||0).toFixed(2),t.pattern,t.entry,t.exit,t.rr,(t.tags||[]).join(\'; \'),t.notes]);\n  const csv=[headers,...rows].map(r=>r.map(v=>`"${String(v??\'\').replace(/"/g,\'""\')}"`).join(\',\')).join(\'\\n\');\n  downloadBlob(new Blob([\'\\ufeff\'+csv],{type:\'text/csv;charset=utf-8\'}),`ledger-${new Date().toISOString().slice(0,10)}.csv`);\n}\nfunction exportJson(){downloadBlob(new Blob([JSON.stringify({exported_at:new Date().toISOString(),trades:TRADES},null,2)],{type:\'application/json\'}),`ledger-backup-${new Date().toISOString().slice(0,10)}.json`)}\nfunction downloadBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement(\'a\');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(u)}\n\nasync function refresh(){\n  try{const data=await api(\'/api/journal\');TRADES=data.trades||[];renderAll()}\n  catch(e){showToast(\'Could not load journal\')}\n  finally{setTimeout(()=>{$(\'splash\').classList.add(\'hide\');setTimeout(()=>$(\'splash\')?.remove(),400)},350)}\n}\nwindow.addEventListener(\'resize\',()=>{clearTimeout(window._chartTimer);window._chartTimer=setTimeout(drawChart,100)});\ndocument.addEventListener(\'keydown\',e=>{if(e.key===\'Escape\'){closeTradeForm();closeLightbox()}});\nif(\'serviceWorker\' in navigator) window.addEventListener(\'load\',()=>navigator.serviceWorker.register(\'/sw.js\').catch(()=>{}));\nrefresh();\n</script>\n</body>\n</html>'

SW_JS = """
self.addEventListener('install', event => self.skipWaiting());
self.addEventListener('activate', event => event.waitUntil(self.clients.claim()));
"""

MANIFEST_JSON = json.dumps({
    "name": "Ledger — Trade Journal",
    "short_name": "Ledger",
    "start_url": "/",
    "display": "standalone",
    "background_color": "#080b14",
    "theme_color": "#080b14",
    "icons": [
        {"src": "/icon-192.png", "sizes": "192x192", "type": "image/png"},
        {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png"},
    ],
})

def utc_now():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")

def clean_text(value, max_len):
    return str(value or "").strip()[:max_len]

def clean_date(value):
    text = clean_text(value, 10)
    try:
        datetime.strptime(text, "%Y-%m-%d")
        return text
    except ValueError:
        return datetime.now().strftime("%Y-%m-%d")

def clean_float(value):
    try:
        number = float(value or 0)
        return number if math.isfinite(number) else 0.0
    except (TypeError, ValueError):
        return 0.0

def clean_screenshot(value):
    value = str(value or "")
    if not value:
        return ""
    if not value.startswith(("data:image/jpeg;base64,", "data:image/png;base64,", "data:image/webp;base64,")):
        return ""
    if len(value) > 4_500_000:
        raise ValueError("Screenshot is too large after compression.")
    return value

def normalize_trade(data, existing=None):
    existing = existing or {}
    symbol = clean_text(data.get("symbol", existing.get("symbol", "")), 24).upper()
    if not symbol:
        raise ValueError("Symbol is required.")

    trade_type = clean_text(data.get("type", existing.get("type", "stock")), 16).lower()
    if trade_type not in ALLOWED_TYPES:
        trade_type = "stock"

    side = clean_text(data.get("side", existing.get("side", "long")), 8).lower()
    if side not in ALLOWED_SIDES:
        side = "long"

    tags = data.get("tags", existing.get("tags", []))
    if not isinstance(tags, list):
        tags = []

    return {
        "id": existing.get("id") or uuid.uuid4().hex,
        "date": clean_date(data.get("date", existing.get("date", ""))),
        "type": trade_type,
        "side": side,
        "symbol": symbol,
        "pnl": clean_float(data.get("pnl", existing.get("pnl", 0))),
        "pattern": clean_text(data.get("pattern", existing.get("pattern", "")), 100),
        "entry": clean_text(data.get("entry", existing.get("entry", "")), 40),
        "exit": clean_text(data.get("exit", existing.get("exit", "")), 40),
        "rr": clean_text(data.get("rr", existing.get("rr", "")), 30),
        "notes": clean_text(data.get("notes", existing.get("notes", "")), 4000),
        "tags": [clean_text(t, 32) for t in tags if clean_text(t, 32)][:10],
        "screenshot": clean_screenshot(data.get("screenshot", existing.get("screenshot", ""))),
        "created_at": existing.get("created_at") or utc_now(),
        "updated_at": utc_now(),
    }

def load_journal():
    global JOURNAL
    os.makedirs(DATA_DIR, exist_ok=True)
    if not os.path.exists(JOURNAL_FILE):
        JOURNAL = []
        return
    try:
        with open(JOURNAL_FILE, "r", encoding="utf-8") as f:
            raw = json.load(f)
        if not isinstance(raw, list):
            raise ValueError("journal.json must contain a list")
        # Backwards-compatible migration of old entries.
        migrated = []
        for item in raw:
            if isinstance(item, dict):
                try:
                    migrated.append(normalize_trade(item, item))
                except ValueError:
                    pass
        JOURNAL = migrated
    except Exception as exc:
        print(f"Warning: could not load {JOURNAL_FILE}: {exc}")
        JOURNAL = []

def save_journal():
    os.makedirs(DATA_DIR, exist_ok=True)
    directory = os.path.dirname(os.path.abspath(JOURNAL_FILE))
    fd, temp_path = tempfile.mkstemp(prefix="ledger-", suffix=".tmp", dir=directory)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(JOURNAL, f, ensure_ascii=False, separators=(",", ":"))
            f.flush()
            os.fsync(f.fileno())
        os.replace(temp_path, JOURNAL_FILE)
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)

class Handler(BaseHTTPRequestHandler):
    server_version = "Ledger/2.0"

    def log_message(self, fmt, *args):
        print(f"{self.address_string()} - {fmt % args}")

    def _common_headers(self):
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header("Permissions-Policy", "camera=(), microphone=(), geolocation=()")

    def _send(self, body, content_type, status=200, cache="no-store"):
        if isinstance(body, str):
            body = body.encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", cache)
        self._common_headers()
        self.end_headers()
        self.wfile.write(body)

    def _json(self, payload, status=200):
        self._send(json.dumps(payload, ensure_ascii=False), "application/json; charset=utf-8", status=status)

    def _read_json(self):
        try:
            length = int(self.headers.get("Content-Length", "0"))
        except ValueError:
            raise ValueError("Invalid Content-Length.")
        if length <= 0:
            return {}
        if length > MAX_BODY_BYTES:
            raise OverflowError("Request is too large.")
        raw = self.rfile.read(length)
        try:
            data = json.loads(raw.decode("utf-8"))
        except Exception:
            raise ValueError("Invalid JSON.")
        if not isinstance(data, dict):
            raise ValueError("JSON body must be an object.")
        return data

    def do_GET(self):
        path = urlsplit(self.path).path
        if path == "/":
            self._send(PAGE_HTML, "text/html; charset=utf-8")
        elif path == "/manifest.json":
            self._send(MANIFEST_JSON, "application/manifest+json; charset=utf-8", cache="public, max-age=3600")
        elif path == "/sw.js":
            self._send(SW_JS, "application/javascript; charset=utf-8", cache="no-cache")
        elif path in {"/icon-512.png", "/icon-192.png", "/apple-touch-icon.png", "/splash-bg.png"}:
            data = {
                "/icon-512.png": ICON_512_B64,
                "/icon-192.png": ICON_192_B64,
                "/apple-touch-icon.png": ICON_180_B64,
                "/splash-bg.png": SPLASH_BG_B64,
            }[path]
            self._send(base64.b64decode(data), "image/png", cache="public, max-age=604800")
        elif path == "/api/journal":
            with LOCK:
                self._json({"ok": True, "trades": JOURNAL})
        elif path == "/healthz":
            self._json({"ok": True})
        else:
            self._json({"ok": False, "error": "Not found"}, status=404)

    def do_POST(self):
        path = urlsplit(self.path).path
        if path not in {"/api/journal", "/api/journal-update", "/api/journal-delete"}:
            self._json({"ok": False, "error": "Not found"}, status=404)
            return

        try:
            data = self._read_json()
            with LOCK:
                if path == "/api/journal":
                    trade = normalize_trade(data)
                    JOURNAL.insert(0, trade)

                elif path == "/api/journal-update":
                    target_id = clean_text(data.get("id"), 64)
                    idx = next((i for i, t in enumerate(JOURNAL) if t.get("id") == target_id), None)
                    if idx is None:
                        self._json({"ok": False, "error": "Trade not found"}, status=404)
                        return
                    JOURNAL[idx] = normalize_trade(data, JOURNAL[idx])

                else:
                    target_id = clean_text(data.get("id"), 64)
                    before = len(JOURNAL)
                    JOURNAL[:] = [t for t in JOURNAL if t.get("id") != target_id]
                    if len(JOURNAL) == before:
                        self._json({"ok": False, "error": "Trade not found"}, status=404)
                        return

                save_journal()
                self._json({"ok": True, "trades": JOURNAL})

        except OverflowError as exc:
            self._json({"ok": False, "error": str(exc)}, status=413)
        except ValueError as exc:
            self._json({"ok": False, "error": str(exc)}, status=400)
        except Exception as exc:
            print(f"Server error: {exc}")
            self._json({"ok": False, "error": "Server error"}, status=500)

def main():
    load_journal()
    server = ThreadingHTTPServer(("0.0.0.0", PORT), Handler)
    print(f"Ledger v2 running on port {PORT}")
    print(f"Journal file: {os.path.abspath(JOURNAL_FILE)}")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nStopped.")
    finally:
        server.server_close()

if __name__ == "__main__":
    main()
